mapper.select:
SELECT count(1)
FROM T_GSQ_STOCK
where IS_DELETE = '0'
and STOCK_DATE = #{stockDate}
and STEEL_RING_CODE = #{steelRingCode}
and ID != #{id}

mapper.update:
UPDATE T_GSQ_STOCK
SET IS_DELETE = 1,
    UPDATE_BY = #{updateBy},
    UPDATE_TIME = #{updateTime}
WHERE DATE_FORMAT(STOCK_DATE, '%Y-%m-%d') = #{stockDateStr}
  AND IS_DELETE = 0
